/**
 * next/image loader for the static export: points each requested width to the file
 * generated by scripts/build-images.mjs (public/images/w/<name>-<width>.webp).
 *
 * Static imports reach the loader as "/_next/static/media/<name>.<hash>.webp". The name picks
 * the generated file; the hash, a fingerprint of the source image, becomes a version query so
 * vercel.json can cache these files for a year: a changed image gets a new URL.
 * tests/rendered-html.test.ts checks every generated URL exists.
 */
export default function imageLoader({ src, width }: { src: string; width: number }): string {
  const fileName = src.split("/").pop() ?? src;
  const [name, fingerprint] = fileName.split(".");
  return `/images/w/${name}-${width}.webp?v=${fingerprint}`;
}
